def signed_reversals(n: int) -> CayleyGraphDef:
    """Cayley graph generated by reverses of all possible signed n(n+1)/2 substrings.

    Actually is a graph for S_2n (n>=1) representing a graph for n elements, where i-th index represents bottom
    side of i-th element, and (n+i)-th index represents top side of i-th element. The graph has n generators
    denoted R[1..1],R[1..2]..R[n..n], where R[i..j] is signed reverse of elements i,i+1..j
    (or actually indexes i..j,n+i..n+j).
    """
    size = 2 * n
    generators = []
    
    # Generate all possible signed reversals R[i..j] for 1 <= i <= j <= n
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            # Create a generator that performs signed reversal of elements i through j
            # This affects indices i-1..j-1 (bottom) and n+i-1..n+j-1 (top)
            def make_generator(start, end):
                def generator(perm):
                    result = list(perm)
                    # Reverse bottom indices (start-1 to end-1)
                    bottom_indices = list(range(start - 1, end))
                    # Reverse top indices (n + start - 1 to n + end - 1)
                    top_indices = list(range(n + start - 1, n + end))
                    
                    # Reverse the bottom part
                    bottom_values = [result[idx] for idx in bottom_indices]
                    bottom_values.reverse()
                    for idx, val in zip(bottom_indices, bottom_values):
                        result[idx] = val
                    
                    # Reverse the top part
                    top_values = [result[idx] for idx in top_indices]
                    top_values.reverse()
                    for idx, val in zip(top_indices, top_values):
                        result[idx] = val
                    
                    # Flip signs (negate) for all affected indices
                    for idx in bottom_indices + top_indices:
                        result[idx] = -result[idx]
                    
                    return tuple(result)
                return generator
            
            generators.append(make_generator(i, j))
    
    # Identity element is the identity permutation with positive signs
    identity = tuple(range(1, size + 1))
    
    return CayleyGraphDef(
        generators=generators,
        identity=identity,
        size=size
    )